import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"简明指南：使用 bind 设置 DNS 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"简明指南：使用 bind 设置 DNS 服务器 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"简明指南：使用 bind 设置 DNS 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"简明指南：使用 bind 设置 DNS 服务器 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200113 How to setup a DNS server with bind","title":"简明指南：使用 bind 设置 DNS 服务器","tag":"202003","desc":""},"relativePath":"202003/20200113 How to setup a DNS server with bind.md","filePath":"[post].md"}'),c={name:"202003/20200113 How to setup a DNS server with bind.md"};function h(g,s,k,b,u,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="简明指南-使用-bind-设置-dns-服务器" tabindex="-1">简明指南：使用 bind 设置 DNS 服务器 <a class="header-anchor" href="#简明指南-使用-bind-设置-dns-服务器" aria-label="Permalink to “简明指南：使用 bind 设置 DNS 服务器”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/dns-server-bind-1-816x345.png" alt=""></p><p><ruby>域名系统<rt>Domain Name System</rt></ruby>，我们更通常称为 DNS 的系统，可以将域名翻译或转换为与该域关联的 IP 地址。DNS 是能够让你通过名称找到自己喜欢的网站而不是在浏览器中输入 IP 地址的原因。本指南将向你展示如何配置一个主 DNS 系统以及客户端。</p><p>以下是本文示例中使用的系统细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dns01.fedora.local    （192.168.1.160）- 主 DNS 服务器</span></span>
<span class="line"><span>client.fedora.local     （192.168.1.136）- 客户端</span></span></code></pre></div><h3 id="dns-服务器配置" tabindex="-1">DNS 服务器配置 <a class="header-anchor" href="#dns-服务器配置" aria-label="Permalink to “DNS 服务器配置”">​</a></h3><p>使用 <code>sudo</code> 安装 bind 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install bind bind-utils -y</span></span></code></pre></div><p>bind 包提供了 <code>/etc/named.conf</code> 配置文件，来供你配置 DNS 服务器。</p><p>编辑 <code>/etc/named.conf</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vi /etc/named.conf</span></span></code></pre></div><p>查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>listen-on port 53 { 127.0.0.1; };</span></span></code></pre></div><p>添加主 DNS 服务器的 IP 地址，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>listen-on port 53 { 127.0.0.1; 192.168.1.160; };</span></span></code></pre></div><p>查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow-query  { localhost; };</span></span></code></pre></div><p>添加本地网络范围。该示例系统使用的 IP 地址在 192.168.1.X 的范围内。指定如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow-query  { localhost; 192.168.1.0/24; };</span></span></code></pre></div><p>指定转发和反向区域。<ruby>区域文件<rt>Zone file</rt></ruby>就是具有系统上 DNS 信息（例如 IP 地址和主机名）的文本文件。<ruby>转发区域文件<rt>forward zone file</rt></ruby>使得将主机名转换为 IP 地址成为可能。<ruby>反向区域文件<rt>reverse zone file</rt></ruby>则相反。它允许远程系统将 IP 地址转换为主机名。</p><p>在 <code>/etc/named.conf</code> 文件的底部查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>include &quot;/etc/named.rfc1912.zones&quot;;</span></span></code></pre></div><p>在此处，你将在<strong>该行的正上方</strong>指定区域文件信息，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;dns01.fedora.local&quot; IN {</span></span>
<span class="line"><span>  type master;</span></span>
<span class="line"><span>  file &quot;forward.fedora.local&quot;;</span></span>
<span class="line"><span>  allow-update { none; };</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.168.192.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>  type master;</span></span>
<span class="line"><span>  file &quot;reverse.fedora.local&quot;;</span></span>
<span class="line"><span>  allow-update { none; };</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>forward.fedora.local</code> 和 <code>reverse.fedora.local</code> 文件是要创建的区域文件的名称。它们可以是任意名字。</p><p>保存并退出。</p><h4 id="创建区域文件" tabindex="-1">创建区域文件 <a class="header-anchor" href="#创建区域文件" aria-label="Permalink to “创建区域文件”">​</a></h4><p>创建你在 <code>/etc/named.conf</code> 文件中指定的转发和反向区域文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /var/named/forward.fedora.local</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL 86400</span></span>
<span class="line"><span>@   IN  SOA     dns01.fedora.local. root.fedora.local. (</span></span>
<span class="line"><span>        2011071001  ;Serial</span></span>
<span class="line"><span>        3600        ;Refresh</span></span>
<span class="line"><span>        1800        ;Retry</span></span>
<span class="line"><span>        604800      ;Expire</span></span>
<span class="line"><span>        86400       ;Minimum TTL</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@       IN  NS          dns01.fedora.local.</span></span>
<span class="line"><span>@       IN  A           192.168.1.160</span></span>
<span class="line"><span>dns01           IN  A   192.168.1.160</span></span>
<span class="line"><span>client          IN  A   192.168.1.136</span></span></code></pre></div><p>所有<strong>粗体</strong>（LCTT 译注：本译文中无法呈现粗体）内容都特定于你的环境。保存文件并退出。接下来，编辑 <code>reverse.fedora.local</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /var/named/reverse.fedora.local</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL 86400</span></span>
<span class="line"><span>@   IN  SOA     dns01.fedora.local. root.fedora.local. (</span></span>
<span class="line"><span>        2011071001  ;Serial</span></span>
<span class="line"><span>        3600        ;Refresh</span></span>
<span class="line"><span>        1800        ;Retry</span></span>
<span class="line"><span>        604800      ;Expire</span></span>
<span class="line"><span>        86400       ;Minimum TTL</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@       IN  NS          dns01.fedora.local.</span></span>
<span class="line"><span>@       IN  PTR         fedora.local.</span></span>
<span class="line"><span>dns01           IN  A   192.168.1.160</span></span>
<span class="line"><span>client          IN  A   192.168.1.136</span></span>
<span class="line"><span>160     IN  PTR         dns01.fedora.local.</span></span>
<span class="line"><span>136     IN  PTR         client.fedora.local.</span></span></code></pre></div><p>所有<strong>粗体</strong>（LCTT 译注：本译文中无法呈现粗体）内容都特定于你的环境。保存文件并退出。</p><p>你还需要配置 SELinux 并为配置文件添加正确的所有权。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chgrp named -R /var/named</span></span>
<span class="line"><span>sudo chown -v root:named /etc/named.conf</span></span>
<span class="line"><span>sudo restorecon -rv /var/named</span></span>
<span class="line"><span>sudo restorecon /etc/named.conf</span></span></code></pre></div><p>配置防火墙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --add-service=dns --perm</span></span>
<span class="line"><span>sudo firewall-cmd --reload</span></span></code></pre></div><h4 id="检查配置是否存在语法错误" tabindex="-1">检查配置是否存在语法错误 <a class="header-anchor" href="#检查配置是否存在语法错误" aria-label="Permalink to “检查配置是否存在语法错误”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo named-checkconf /etc/named.conf</span></span></code></pre></div><p>如果没有输出或返回错误，那么你的配置有效。</p><p>检查转发和反向区域文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo named-checkzone forward.fedora.local /var/named/forward.fedora.local</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo named-checkzone reverse.fedora.local /var/named/reverse.fedora.local</span></span></code></pre></div><p>你应该看到 “OK” 的响应：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone forward.fedora.local/IN: loaded serial 2011071001</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone reverse.fedora.local/IN: loaded serial 2011071001</span></span>
<span class="line"><span>OK</span></span></code></pre></div><h4 id="启用并启动-dns-服务" tabindex="-1">启用并启动 DNS 服务 <a class="header-anchor" href="#启用并启动-dns-服务" aria-label="Permalink to “启用并启动 DNS 服务”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable named</span></span>
<span class="line"><span>$ sudo systemctl start named</span></span></code></pre></div><h4 id="配置-resolv-conf-文件" tabindex="-1">配置 resolv.conf 文件 <a class="header-anchor" href="#配置-resolv-conf-文件" aria-label="Permalink to “配置 resolv.conf 文件”">​</a></h4><p>编辑 <code>/etc/resolv.conf</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/resolv.conf</span></span></code></pre></div><p>查找你当前的 <code>nameserver</code> 行。在示例系统上，使用调制解调器/路由器充当名称服务器，因此当前看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.1</span></span></code></pre></div><p>这需要更改为主 DNS 服务器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.160</span></span></code></pre></div><p>保存更改并退出。</p><p>不幸的是需要注意一点。如果系统重启或网络重启，那么 NetworkManager 会覆盖 <code>/etc/resolv.conf</code> 文件。这意味着你将丢失所做的所有更改。</p><p>为了防止这种情况发生，请将 <code>/etc/resolv.conf</code> 设为不可变：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr +i /etc/resolv.conf</span></span></code></pre></div><p>如果要重新设置，就需要允许其再次被覆盖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr -i /etc/resolv.conf</span></span></code></pre></div><h4 id="测试-dns-服务器" tabindex="-1">测试 DNS 服务器 <a class="header-anchor" href="#测试-dns-服务器" aria-label="Permalink to “测试 DNS 服务器”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; &lt;&lt;&gt;&gt; DiG 9.11.13-RedHat-9.11.13-2.fc30 &lt;&lt;&gt;&gt; fedoramagazine.org</span></span>
<span class="line"><span>;; global options: +cmd</span></span>
<span class="line"><span>;; Got answer:</span></span>
<span class="line"><span>;; -&gt;&gt;HEADER&lt;&lt;- opcode: QUERY, status: NOERROR, id: 8391</span></span>
<span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; OPT PSEUDOSECTION:</span></span>
<span class="line"><span> ; EDNS: version: 0, flags:; udp: 4096</span></span>
<span class="line"><span> ; COOKIE: c7350d07f8efaa1286c670ab5e13482d600f82274871195a (good)</span></span>
<span class="line"><span> ;; QUESTION SECTION:</span></span>
<span class="line"><span> ;fedoramagazine.org.        IN  A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    50  IN  A   35.197.52.145</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; AUTHORITY SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns05.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns02.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns04.fedoraproject.org.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ADDITIONAL SECTION:</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  A   152.19.134.139</span></span>
<span class="line"><span> ns04.fedoraproject.org.    86150   IN  A   209.132.181.17</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  A   85.236.55.10</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  AAAA    2610:28:3090:3001:dead:beef:cafe:fed5</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  AAAA    2001:4178:2:1269:dead:beef:cafe:fed5</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ;; Query time: 830 msec</span></span>
<span class="line"><span> ;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span>
<span class="line"><span> ;; WHEN: Mon Jan 06 08:46:05 CST 2020</span></span>
<span class="line"><span> ;; MSG SIZE  rcvd: 266</span></span></code></pre></div><p>需要检查几件事以验证 DNS 服务器是否正常运行。显然，取得结果很重要，但这本身并不意味着 DNS 服务器实际上正常工作。</p><p>顶部的 <code>QUERY</code>、<code>ANSWER</code> 和 <code>AUTHORITY</code> 字段应显示为非零，如我们的示例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span></code></pre></div><p>并且 <code>SERVER</code> 字段应有你的 DNS 服务器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span></code></pre></div><p>如果这是你第一次运行 <code>dig</code> 命令，请注意完成查询要花费 830 毫秒的时间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; Query time: 830 msec</span></span></code></pre></div><p>如果再次运行它，查询将会更快：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; Query time: 0 msec</span></span>
<span class="line"><span>;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span></code></pre></div><h3 id="客户端配置" tabindex="-1">客户端配置 <a class="header-anchor" href="#客户端配置" aria-label="Permalink to “客户端配置”">​</a></h3><p>客户端配置将简单得多。</p><p>安装 bind 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install bind-utils -y</span></span></code></pre></div><p>编辑 <code>/etc/resolv.conf</code> 文件，并将主 DNS 配置为唯一的名称服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/resolv.conf</span></span></code></pre></div><p>它看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.160</span></span></code></pre></div><p>保存更改并退出。然后，使 <code>/etc/resolv.conf</code> 文件不可变，防止其被覆盖并变回默认设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr +i /etc/resolv.conf</span></span></code></pre></div><h4 id="测试客户端" tabindex="-1">测试客户端 <a class="header-anchor" href="#测试客户端" aria-label="Permalink to “测试客户端”">​</a></h4><p>你应该获得与 DNS 服务器相同的结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; &lt;&lt;&gt;&gt; DiG 9.11.13-RedHat-9.11.13-2.fc30 &lt;&lt;&gt;&gt; fedoramagazine.org</span></span>
<span class="line"><span>;; global options: +cmd</span></span>
<span class="line"><span>;; Got answer:</span></span>
<span class="line"><span>;; -&gt;&gt;HEADER&lt;&lt;- opcode: QUERY, status: NOERROR, id: 8391</span></span>
<span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; OPT PSEUDOSECTION:</span></span>
<span class="line"><span> ; EDNS: version: 0, flags:; udp: 4096</span></span>
<span class="line"><span> ; COOKIE: c7350d07f8efaa1286c670ab5e13482d600f82274871195a (good)</span></span>
<span class="line"><span> ;; QUESTION SECTION:</span></span>
<span class="line"><span> ;fedoramagazine.org.        IN  A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    50  IN  A   35.197.52.145</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; AUTHORITY SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns05.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns02.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns04.fedoraproject.org.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ADDITIONAL SECTION:</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  A   152.19.134.139</span></span>
<span class="line"><span> ns04.fedoraproject.org.    86150   IN  A   209.132.181.17</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  A   85.236.55.10</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  AAAA    2610:28:3090:3001:dead:beef:cafe:fed5</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  AAAA    2001:4178:2:1269:dead:beef:cafe:fed5</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ;; Query time: 1 msec</span></span>
<span class="line"><span> ;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span>
<span class="line"><span> ;; WHEN: Mon Jan 06 08:46:05 CST 2020</span></span>
<span class="line"><span> ;; MSG SIZE  rcvd: 266</span></span></code></pre></div><p>确保 <code>SERVER</code> 输出的是你 DNS 服务器的 IP 地址。</p><p>你的 DNS 服务器设置完成了，现在所有来自客户端的请求都会经过你的 DNS 服务器了！</p><hr>`,92)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://fedoramagazine.org/how-to-setup-a-dns-server-with-bind/"},{default:i(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/how-to-setup-a-dns-server-with-bind/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://fedoramagazine.org/author/rcurtiswarfield/"},{default:i(()=>[...s[2]||(s[2]=[a("Curt Warfield",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const N=l(c,[["render",h]]);export{v as __pageData,N as default};
